<script setup lang="ts">
import type {DecorationBlock,DecorationOptions,DecorationRoute} from '../../../../api/src/core/decoration-types'
import {frameworkAsset,fillOrderDefaults} from '../../../../api/src/core/decoration-framework.mjs'
import {decorationOptions} from '../../../../api/src/core/decoration-options.mjs'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsolePagePathPicker from './ConsolePagePathPicker.vue'
import ImageSelectTile from './ImageSelectTile.vue'
import DecorationVisualPicker from './DecorationVisualPicker.vue'
const props=defineProps<{disabled?:boolean;routes:DecorationRoute[];imageUrl:(id:string)=>string}>()
const block=defineModel<DecorationBlock>({required:true})
defineEmits<{pick:[target:{itemId?:string}]}>()
const o=computed(()=>decorationOptions(block.value))
function addOrder(){if(props.disabled||block.value.items.length>=8)return;block.value.items.push({id:crypto.randomUUID(),label:'新入口',imageId:null,icon:'receipt-text',target:'',enabled:true})}
function moveOrder(index:number,offset:number){if(props.disabled||index+offset<0||index+offset>=block.value.items.length)return;const [entry]=block.value.items.splice(index,1);block.value.items.splice(index+offset,0,entry!)}
function set(key:keyof DecorationOptions,value:unknown){if(!props.disabled)block.value.options={...block.value.options,[key]:value}}

</script>
<template><section v-if="['intro','features','orders'].includes(block.type)" class="framework-content-fields"><UFormField label="标题"><UTextarea v-if="block.type==='intro'" v-model="block.title" :rows="2" :maxlength="60" :disabled="disabled" class="w-full"/><ConsoleInput v-else v-model="block.title" :maxlength="60" :disabled="disabled"/></UFormField><UFormField v-if="['intro','features'].includes(block.type)" :label="block.type==='intro'?'简介':'底部说明'"><UTextarea v-model="block.text" :rows="2" :maxlength="500" :disabled="disabled" class="w-full"/></UFormField>
<template v-if="block.type==='intro'"><UFormField label="顶部文字"><ConsoleInput :model-value="o.eyebrow" :maxlength="30" :disabled="disabled" @update:model-value="set('eyebrow',$event)"/></UFormField><UFormField label="按钮文字"><ConsoleInput :model-value="o.buttonText" :maxlength="20" :disabled="disabled" @update:model-value="set('buttonText',$event)"/></UFormField><UFormField label="按钮跳转"><ConsolePagePathPicker v-model="block.target" :options="routes" :disabled="disabled"/></UFormField><ImageSelectTile :src="block.imageId?imageUrl(block.imageId):frameworkAsset('intro.webp')" label="介绍背景图" :disabled="disabled" :removable="!!block.imageId" @select="$emit('pick',{})" @remove="block.imageId=null"/></template>
<template v-if="block.type==='orders'"><UFormField label="全部订单入口"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField><div v-if="!block.items.length&&routes.some(route=>route.orderEntry==='shortcut')" class="order-defaults"><p>尚未配置订单快捷入口</p><UButton color="neutral" variant="outline" size="sm" :disabled="disabled" @click="fillOrderDefaults(block,routes)">使用默认订单入口</UButton></div><div class="order-entry-toolbar"><strong>快捷入口</strong><UButton v-if="block.items.length&&routes.some(route=>route.orderEntry==='shortcut'&&!block.items.some(item=>item.target===route.key))" color="neutral" variant="outline" size="sm" :disabled="disabled||block.items.length>=8" @click="fillOrderDefaults(block,routes,true)">补齐默认入口</UButton><UButton color="neutral" variant="outline" size="sm" icon="i-lucide-plus" :disabled="disabled||block.items.length>=8" @click="addOrder">添加入口</UButton></div></template>

<section v-for="(item,index) in block.items" :key="item.id" class="framework-item-fields"><div v-if="block.type==='orders'" class="order-entry-toolbar"><USwitch :model-value="item.enabled!==false" :disabled="disabled" :aria-label="'显示订单入口 '+(index+1)" @update:model-value="item.enabled=$event"/><span>入口 {{index+1}}</span><div class="order-entry-actions"><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-up" :aria-label="'上移订单入口 '+(index+1)" :disabled="disabled||index===0" @click="moveOrder(index,-1)"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-down" :aria-label="'下移订单入口 '+(index+1)" :disabled="disabled||index===block.items.length-1" @click="moveOrder(index,1)"/><UButton color="error" variant="ghost" size="xs" icon="i-lucide-trash-2" :aria-label="'删除订单入口 '+(index+1)" :disabled="disabled" @click="block.items.splice(index,1)"/></div></div><UFormField label="名称"><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled"/></UFormField><DecorationVisualPicker v-model:image-id="item.imageId" v-model:icon="item.icon" :label="item.label+'图标'" :image-url="imageUrl" :disabled="disabled" fallback-icon="layout-grid" @pick="$emit('pick',{itemId:item.id})"/><UFormField v-if="block.type==='features'" label="能力说明"><UTextarea v-model="item.text" :rows="2" :maxlength="500" :disabled="disabled" class="w-full"/></UFormField><UFormField label="跳转目标"><ConsolePagePathPicker v-model="item.target" :options="routes" allow-empty :disabled="disabled"/></UFormField></section></section></template>
<style scoped>.framework-content-fields,.framework-item-fields{display:grid;gap:18px}.framework-item-fields{border-top:1px solid var(--ui-border);padding-top:18px}.order-entry-toolbar{display:flex;align-items:center;gap:8px;font-size:12px}.order-entry-toolbar>strong{margin-right:auto}.order-entry-actions{display:flex;gap:2px;margin-left:auto}.order-defaults{display:grid;gap:10px;color:var(--ui-text-muted);font-size:12px;padding:12px;border:1px dashed var(--ui-border);border-radius:8px}</style>
